"""Verify the exact native-tested, matched prerelease before publication."""
import argparse
import hashlib
import json
from pathlib import Path
import struct
import zipfile


def require(condition, message):
    if not condition:
        raise RuntimeError(message)


def verify(artifact, commit, output):
    version = '1.3.0-pre.1'
    package = artifact / 'dist' / f'l4d2-bridge-patch-v{version}.zip'
    checksum = hashlib.sha256(package.read_bytes()).hexdigest()
    require((artifact / 'dist/SHA256SUMS.txt').read_text().strip()
            == f'{checksum}  {package.name}', 'Archive checksum mismatch')
    with zipfile.ZipFile(package) as archive:
        info = json.loads(archive.read('BUILD-INFO.json'))
        require(info['release_version'] == version and info['source_commit'] == commit,
                'Wrong version or compilation commit')
        require(info['distribution'] == 'prerelease' and info['build_type'] == 'Release',
                'Expected prerelease Release compilation')
        require(info['default_batch'] == 8 and info['mapped_default_enabled'] is False,
                'Defaults must be C8 and mapping disabled')
        require(info['legacy_data_ring'] is False and info['reply_v2'] is True
                and info['upload_leases'] is True and info['reply_slots'] is False,
                'Unexpected IPC transport')
        require(info['gameplay_validated'] is False, 'Do not infer game validation from CI')
        require(archive.read('VERSION').decode().strip() == version, 'Package VERSION mismatch')
        expected = {'bin/dxvk_d3d9.dll': 0x14c,
                    'bin/.l4d2bridge/L4D2Bridge32.exe': 0x14c,
                    'bin/.l4d2bridge/L4D2Bridge64.exe': 0x8664}
        require(set(info['files']) == set(expected), 'Expected only matched three binaries')
        require({name for name in archive.namelist() if name.startswith('bin/')}
                == set(expected), 'Package must preserve existing configuration and backends')
        require(info['build_id'].startswith(f'l4d2-{version}+'), 'Wrong embedded build prefix')
        for name, machine in expected.items():
            data = archive.read(name)
            require(hashlib.sha256(data).hexdigest() == info['files'][name], name + ' checksum')
            require(info['build_id'].encode() in data, name + ' build stamp')
            pe = struct.unpack_from('<I', data, 60)[0]
            require(struct.unpack_from('<H', data, pe + 4)[0] == machine, name + ' architecture')
            if name.endswith('32.exe'):
                require(struct.unpack_from('<H', data, pe + 22)[0] & 0x20, 'x86 Host must be LAA')
        output.mkdir(parents=True, exist_ok=True)
        (output / 'BUILD-INFO.json').write_bytes(archive.read('BUILD-INFO.json'))
        (output / 'INSTALL.zh-CN.md').write_bytes(archive.read('INSTALL-AND-TEST.md'))
    require(json.loads((artifact / 'work/ipc-full-build.json').read_text())['build_id']
            == info['build_id'], 'Preparation and package stamps differ')
    rows = json.loads((artifact / 'work/ipc-full-native/full-native-results.json').read_text())
    batches = {'1', '2', '4', '8', '16', '32'}
    require(len(rows) == 360 and all(row['client_rc'] == row['host_rc'] == 0 for row in rows),
            'All 360 native pairs must pass')
    require({(row['iteration'], row['batch'], row['host_arch'], row['mode']) for row in rows}
            == {(iteration, batch, arch, mode) for iteration in range(3) for batch in batches
                for arch in ('32', '64') for mode in {row['mode'] for row in rows}},
            'Missing native round, gear, architecture or mode')
    faults = json.loads((artifact / 'work/ipc-full-native/full-native-fault-results.json').read_text())
    require(len(faults) == 24 and all(row['rc'] == 0 for row in faults),
            'All 24 fail-closed cases must pass')
    costs = json.loads((artifact / 'work/vbib-mapped-native/cost-raw.json').read_text())
    require(len(costs) == 24 and all(row['rc'] == 0 and len(row['rows']) == 20 for row in costs),
            'Native storage comparison incomplete')
    (output / 'PACKAGE-VERIFICATION.json').write_text(json.dumps(dict(
        version=version, commit=commit, build_id=info['build_id'], zip=package.name,
        zip_sha256=checksum, native_pairs=len(rows), fail_closed=len(faults),
        cost_processes=len(costs), default_batch=8, mapped_default_enabled=False), indent=2) + '\n')
    print('VERIFIED', info['build_id'], checksum)


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--artifact', type=Path, required=True)
    parser.add_argument('--commit', required=True)
    parser.add_argument('--output', type=Path, required=True)
    args = parser.parse_args()
    verify(args.artifact, args.commit, args.output)
